// ── source: vcx/tests/module_loader_shadowing_test.v ──

// #701 — module loader: in-memory conformance fixture sources must NOT
// shadow user files in production binaries (fixture-before-fix pin).
//
// Before the fix, `register_conformance_test_modules` ran unconditionally in
// `new_seeded_module_table()` (the production module-table constructor), and
// `resolve_lib` gives `registered_sources` precedence over disk for
// `.file_path` resolvers — so a user program with `[?lib './local-helpers.cx']`
// silently resolved to the embedded fixture source ("hello, …") instead of
// the user's own file. No error, wrong code runs.
//
// This test IS the production scenario: a real file on disk whose path
// collides with a fixture resolver key. The user's file MUST win. The
// conformance gate keeps its hermetic in-memory sources by EXPLICIT
// registration in the test runner (code_eval_fixtures_test.v), never in the
// production constructor.
fn test_user_file_wins_over_fixture_resolver_key() {
	tmp := os.join_path(os.temp_dir(), 'cx_issue701_shadowing')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp)!
	// Same resolver key as the conformance fixture, DIFFERENT body.
	os.write_file(os.join_path(tmp, 'local-helpers.cx'), '[?def greet scope=public (\$name) [\$concat "ahoy, " \$name]]')!
	old_cwd := os.getwd()
	os.chdir(tmp)!
	defer {
		os.chdir(old_cwd) or {}
		os.rmdir_all(tmp) or {}
	}
	prog := "[?lib './local-helpers.cx' as=helpers]\n[\$helpers:greet \"skipper\"]"
	out := code.eval_code('', prog, 'text') or { panic('eval failed: ${err}') }
	assert out.contains('ahoy, skipper'), 'user file on disk must win over the embedded fixture source; got: ${out}'
}

// The inverse guard: with NOTHING registered and NO file on disk, the
// file-path resolver must fail loud (MODULE_FILE_NOT_FOUND) — never fall
// back to any embedded source.
fn test_missing_user_file_fails_loud() {
	tmp := os.join_path(os.temp_dir(), 'cx_issue701_missing')
	os.rmdir_all(tmp) or {}
	os.mkdir_all(tmp)!
	old_cwd := os.getwd()
	os.chdir(tmp)!
	defer {
		os.chdir(old_cwd) or {}
		os.rmdir_all(tmp) or {}
	}
	prog := "[?lib './public-only-module.cx' as=m]\n[\$m:exported-fn 1]"
	if out := code.eval_code('', prog, 'text') {
		assert false, 'expected MODULE_FILE_NOT_FOUND, got success: ${out}'
	} else {
		assert err.msg().contains('MODULE_FILE_NOT_FOUND'), 'expected MODULE_FILE_NOT_FOUND, got: ${err.msg()}'
	}
}

// ── source: vcx/tests/module_loader_test.v ──
// Tests for the Phase 2.13 + 2.14 standalone module loader
// (`vcx/code/module_loader.v`)
// spec/lockfile.md §4.4.
//
// The loader under test is `code.load_module(source, name, mut table)`
// plus `code.resolve_lib(node, mut table)` + `code.verify_sri(integ,
// content)`. Coverage targets:
//
//   - Two-pass load: single-module + multi-module + transitive.
//   - Cycle detection (cross-module A↔B) — MODULE_CYCLE_DETECTED.
//   - SRI shape validation (sha384 / sha512 well-formed + malformed).
//   - SRI digest verification (matching + mismatching content).
//   - HTTPS resolver — returns MODULE_HTTPS_FETCH_DEFERRED.
//   - Registered-name resolver — looks up in-memory map.
//   - File-path resolver — round-trips a temp file under base_dir.
//   - [?const] dependency ordering — Kahn's algorithm: a const that
//     references another const is evaluated AFTER its dep.
//   - Duplicate-name diagnostic.
//
// All fixtures are synthetic in-process strings — Phase 2.13 partial
// scope skips real on-disk fixtures (Phase 2.x graft).
// ── 1. Single-module load (no libs) → module is callable ─────────────────────

fn test_module_loader_single_module_no_libs() {
	src := '[?def double ($x) [* x 2]]
[?const FORTY-TWO [double 21]]'
	mut table := code.new_module_table()
	mod := code.load_module(src, 'm-single', mut table) or {
		panic('expected load success, got: ${err}')
	}
	assert mod.name == 'm-single'
	assert mod.defs.len == 1
	assert 'double' in mod.defs
	assert mod.consts.len == 1
	assert 'FORTY-TWO' in mod.consts
	assert mod.libs.len == 0
	// Module is registered in the table.
	assert 'm-single' in table.modules
}

// ── 2. Two-module load — A imports B (registered-name) ───────────────────────

fn test_module_loader_two_modules_a_imports_b() {
	mut table := code.new_module_table()
	src_b := '[?def helper ($x) [+ x 1]]'
	table.register_source('mod-b', src_b)
	src_a := '[?lib "mod-b"]
[?def caller ($x) [helper x]]'
	mod_a := code.load_module(src_a, 'mod-a', mut table) or {
		panic('expected load success, got: ${err}')
	}
	assert mod_a.libs.len == 1
	assert mod_a.libs[0].resolver_source == 'mod-b'
	// mod-b loaded transitively.
	assert 'mod-b' in table.modules
	mod_b := table.modules['mod-b'] or { panic('mod-b not registered') }
	assert 'helper' in mod_b.defs
}

// ── 3. Cycle detection — A imports B, B imports A → MODULE_CYCLE_DETECTED ───

fn test_module_loader_cycle_detected() {
	mut table := code.new_module_table()
	table.register_source('cycle-a', '[?lib "cycle-b"]')
	table.register_source('cycle-b', '[?lib "cycle-a"]')
	if _ := code.load_module('[?lib "cycle-b"]', 'cycle-a', mut table) {
		panic('expected cycle error, got success')
	} else {
		assert err.msg().contains('MODULE_CYCLE_DETECTED') || err.msg().contains('CXER0210')
	}
}

// ── 4. SRI sha384 well-formed shape passes shape check ───────────────────────

fn test_module_loader_sri_sha384_shape_valid() {
	// A real sha384 digest (48 bytes) of "hello" — base64-encoded.
	digest := sha512.sum384('hello'.bytes())
	encoded := base64.encode(digest)
	sri := 'sha384-${encoded}'
	shape := code.verify_sri_shape(sri) or {
		panic('expected shape valid, got: ${err}')
	}
	assert shape.algo == 'sha384'
	assert shape.expected_digest.len == 48
}

// ── 5. SRI sha512 well-formed shape passes shape check ───────────────────────

fn test_module_loader_sri_sha512_shape_valid() {
	digest := sha512.sum512('hello'.bytes())
	encoded := base64.encode(digest)
	sri := 'sha512-${encoded}'
	shape := code.verify_sri_shape(sri) or {
		panic('expected shape valid, got: ${err}')
	}
	assert shape.algo == 'sha512'
	assert shape.expected_digest.len == 64
}

// ── 6. SRI malformed prefix raises MODULE_SRI_MALFORMED ──────────────────────

fn test_module_loader_sri_malformed_prefix() {
	if _ := code.verify_sri_shape('md5-AAAA') {
		panic('expected malformed error, got success')
	} else {
		assert err.msg().contains('MODULE_SRI_MALFORMED')
		assert err.msg().contains('md5')
	}
}

// ── 7. SRI missing dash raises MODULE_SRI_MALFORMED ──────────────────────────

fn test_module_loader_sri_missing_dash() {
	if _ := code.verify_sri_shape('sha384AAAA') {
		panic('expected malformed error, got success')
	} else {
		assert err.msg().contains('MODULE_SRI_MALFORMED')
	}
}

// ── 8. SRI verify digest match returns true ──────────────────────────────────

fn test_module_loader_sri_digest_match() {
	content := 'hello world'
	digest := sha512.sum384(content.bytes())
	encoded := base64.encode(digest)
	sri := 'sha384-${encoded}'
	matched := code.verify_sri(sri, content) or {
		panic('expected verify success, got: ${err}')
	}
	assert matched == true
}

// ── 9. SRI verify digest mismatch returns false ──────────────────────────────

fn test_module_loader_sri_digest_mismatch() {
	// SRI computed over "hello" but content is "goodbye".
	digest := sha512.sum384('hello'.bytes())
	encoded := base64.encode(digest)
	sri := 'sha384-${encoded}'
	matched := code.verify_sri(sri, 'goodbye') or {
		panic('expected verify shape valid, got: ${err}')
	}
	assert matched == false
}

// ── 10. HTTPS resolution — the Phase-2.14 pin/verify/cache contract ──────────
// (register R3.12, RULED (b) 2026-08-09; code.md §12.1.3, lockfile.md §4/§5)

const mlt_mod_src = '[?def version scope=public () "9.9.9"]'

fn mlt_lock_table(url string, sri string) code.ModuleTable {
	mut table := code.new_module_table()
	table.lockfile = cx.parse_lockfile_text('[cx.lock version=1 [modules [module name="${url}" resolved="${url}" sri="${sri}"]]]') or {
		panic('seed lockfile: ${err}')
	}
	table.lock_probed = true
	return table
}

// no lockfile at all → an HTTPS resolver is unpinned remote code, refused
// BEFORE any transport or registry consultation.
fn test_module_loader_https_unpinned_refuses() {
	mut table := code.new_module_table()
	table.lock_probed = true // no cx.lock — the empty-pin posture
	node := cx.parse_lib('[?lib "https://cdn.example.com/regex-1.2.3.zip"]') or {
		panic('parse_lib failed: ${err}')
	}
	if _ := code.resolve_lib(node, mut table) {
		panic('expected MODULE_UNPINNED, got success')
	} else {
		assert err.msg().contains('MODULE_UNPINNED')
	}
}

// pinned + registry bytes matching the sri → loads; verification is real.
fn test_module_loader_https_pinned_match_loads() {
	url := 'https://cdn.example.com/mlt-ok-1.0.0.zip'
	sri := code.make_sri('sha384', mlt_mod_src) or { panic('sri: ${err}') }
	mut table := mlt_lock_table(url, sri)
	table.register_source(url, mlt_mod_src)
	node := cx.parse_lib('[?lib "${url}" as=mlt]') or { panic('parse_lib failed: ${err}') }
	mod := code.resolve_lib(node, mut table) or { panic('pinned+matching must load: ${err}') }
	assert 'version' in mod.defs
}

// pinned + tampered bytes → MODULE_SRI_MISMATCH, and NOTHING lands in the
// on-disk cache (lockfile.md §4.4 — a poisoned fetch is never cached).
fn test_module_loader_https_mismatch_refuses_and_never_caches() {
	cache := os.join_path(os.temp_dir(), 'cx-mlt-cache-${os.getpid()}')
	os.rmdir_all(cache) or {}
	os.setenv('CX_MODULE_CACHE', cache, true)
	defer {
		os.unsetenv('CX_MODULE_CACHE')
		os.rmdir_all(cache) or {}
	}
	url := 'https://cdn.example.com/mlt-tampered-1.0.0.zip'
	sri := code.make_sri('sha384', mlt_mod_src) or { panic('sri: ${err}') }
	mut table := mlt_lock_table(url, sri)
	table.register_source(url, mlt_mod_src + '\n[; drift ]')
	node := cx.parse_lib('[?lib "${url}"]') or { panic('parse_lib failed: ${err}') }
	if _ := code.resolve_lib(node, mut table) {
		panic('expected MODULE_SRI_MISMATCH, got success')
	} else {
		assert err.msg().contains('MODULE_SRI_MISMATCH')
	}
	if os.exists(cache) {
		assert os.ls(cache) or { []string{} }.len == 0, 'mismatched bytes must never be cached'
	}
}

// pinned + on-disk cache hit → loads with NO registry entry and NO network
// (the cache is (url, sri)-keyed; bytes still verify on every load).
fn test_module_loader_https_cache_hit_loads() {
	cache := os.join_path(os.temp_dir(), 'cx-mlt-cache-hit-${os.getpid()}')
	os.rmdir_all(cache) or {}
	os.mkdir_all(cache) or { panic('mkdir: ${err}') }
	os.setenv('CX_MODULE_CACHE', cache, true)
	defer {
		os.unsetenv('CX_MODULE_CACHE')
		os.rmdir_all(cache) or {}
	}
	url := 'https://cdn.example.com/mlt-cached-1.0.0.zip'
	sri := code.make_sri('sha384', mlt_mod_src) or { panic('sri: ${err}') }
	os.write_file(code.module_cache_path_for_test(url, sri), mlt_mod_src) or {
		panic('seed cache: ${err}')
	}
	mut table := mlt_lock_table(url, sri)
	node := cx.parse_lib('[?lib "${url}" as=cached]') or { panic('parse_lib failed: ${err}') }
	mod := code.resolve_lib(node, mut table) or { panic('cache hit must load: ${err}') }
	assert 'version' in mod.defs
}

